tile_node_cpu.query:
timeseries avg(`custom.proxmox.node.cpu.usage`), by: {node_name, cluster_name}
| filter cluster_name == $cluster_name
| filter isNull(array($node_name)[0]) or in(node_name, array($node_name))

tile_node_loadavg.query:
timeseries {
  avg1  = avg(`custom.proxmox.node.loadavg.1m`),
  avg5  = avg(`custom.proxmox.node.loadavg.5m`),
  avg15 = avg(`custom.proxmox.node.loadavg.15m`)
}, by: {node_name, cluster_name}
| filter cluster_name == $cluster_name
| filter isNull(array($node_name)[0]) or in(node_name, array($node_name))

tile_node_memory.query:
timeseries {
  used  = avg(`custom.proxmox.node.memory.used`),
  free  = avg(`custom.proxmox.node.memory.free`),
  total = avg(`custom.proxmox.node.memory.total`)
}, by: {node_name, cluster_name}
| filter cluster_name == $cluster_name
| filter isNull(array($node_name)[0]) or in(node_name, array($node_name))

